:root {
  --blue: #2563eb;
  --blue-soft: #eff6ff;
  --green: #16a34a;
  --green-bg: #dcfce7;
  --ink: #0f172a;
  --muted: #64748b;
  --border: #dbe4ef;
  --surface: #ffffff;
  --page: #f8fafc;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  box-sizing: border-box;
  background: transparent;
  font-family: "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

.panel {
  height: 100%;
  display: flex;
  flex-direction: column;
  background: transparent;
  color: var(--ink);
}

.panel-title {
  height: 26px;
  display: flex;
  align-items: center;
  padding: 0 2px 8px 2px;
  font-size: 10px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: 0.45px;
  color: #64748b;
  text-transform: uppercase;
}

.list {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: row;
  gap: 10px;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 1px 3px 6px 1px;
  scrollbar-width: thin;
}

.card {
  appearance: none;
  flex: 0 0 250px;
  width: 250px;
  min-width: 250px;
  min-height: 92px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface);
  padding: 12px 12px 11px 12px;
  text-align: left;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.025);
  transition: border-color 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}

.card:hover {
  border-color: #93b4ff;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.08);
  transform: translateY(-1px);
}

.card.selected {
  border: 2px solid var(--blue);
  padding: 11px 11px 10px 11px;
  box-shadow: 0 3px 10px rgba(37, 99, 235, 0.1);
}

.card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.ref {
  min-width: 0;
  font-size: 9px;
  line-height: 1.25;
  font-weight: 750;
  color: #64748b;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.badge {
  flex: 0 0 auto;
  border-radius: 4px;
  padding: 3px 6px;
  background: var(--green-bg);
  color: var(--green);
  font-size: 8px;
  line-height: 1;
  font-weight: 850;
  letter-spacing: 0.25px;
  text-transform: uppercase;
  white-space: nowrap;
}

.group-name {
  margin-top: 7px;
  font-size: 15px;
  line-height: 1.25;
  font-weight: 800;
  color: var(--ink);
}

.meta {
  margin-top: 7px;
  font-size: 10px;
  line-height: 1.25;
  font-weight: 550;
  color: var(--muted);
}

.empty,
.loading {
  flex: 1;
  min-height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
  border: 1px dashed #cbd5e1;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.75);
  color: #64748b;
  font-size: 12px;
  text-align: center;
}

